<?php echo "--- NOMINATIM TEST ---<br>"; $ch1 = curl_init('https://nominatim.openstreetmap.org/search?q=Paris&format=json&limit=1'); curl_setopt($ch1, CURLOPT_RETURNTRANSFER, true); curl_setopt($ch1, CURLOPT_TIMEOUT, 15); curl_setopt($ch1, CURLOPT_USERAGENT, 'WanderAI-Test/1.0'); $r1 = curl_exec($ch1); echo $r1 === false ? 'FAILED: ' . curl_error($ch1) : htmlspecialchars($r1); echo "<br><br>--- OVERPASS REAL QUERY TEST (Paris coords) ---<br>"; $query = '[out:json][timeout:15];(node["tourism"="attraction"](around:5000,48.8566,2.3522););out body 20;'; $ch2 = curl_init('https://overpass-api.de/api/interpreter'); curl_setopt($ch2, CURLOPT_POST, true); curl_setopt($ch2, CURLOPT_POSTFIELDS, ['data' => $query]); curl_setopt($ch2, CURLOPT_RETURNTRANSFER, true); curl_setopt($ch2, CURLOPT_TIMEOUT, 25); $r2 = curl_exec($ch2); echo $r2 === false ? 'FAILED: ' . curl_error($ch2) : 'Got ' . strlen($r2) . ' bytes. First 500 chars: <br>' . htmlspecialchars(substr($r2, 0, 500));